class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])

        # dp[i][j][k] = max coins to reach (i,j) with exactly k neutralizations used (k=0,1,2)
        dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]

        # Base case
        dp[0][0][0] = coins[0][0]

        # Fill the DP table
        for i in range(m):
            for j in range(n):
                current_coin = coins[i][j]

                # Try coming from above
                if i > 0:
                    for k in range(3):
                        if dp[i-1][j][k] != -float('inf'):
                            # If we neutralize current robber
                            if current_coin < 0 and k < 2:
                                dp[i][j][k+1] = max(dp[i][j][k+1], dp[i-1][j][k] + current_coin)
                            else:
                                # Don't neutralize (either not a robber or no neutralization left)
                                dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + current_coin)

                # Try coming from left  
                if j > 0:
                    for k in range(3):
                        if dp[i][j-1][k] != -float('inf'):
                            # If we neutralize current robber
                            if current_coin < 0 and k < 2:
                                dp[i][j][k+1] = max(dp[i][j][k+1], dp[i][j-1][k] + current_coin)
                            else:
                                # Don't neutralize (either not a robber or no neutralization left)
                                dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + current_coin)

        # Return the maximum among all possible neutralizations at destination
        return max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        total_sum = sum(nums)
        left_sum = 0
        count = 0

        # Iterate through all possible partitions (i from 0 to n-2)
        for i in range(len(nums) - 1):
            left_sum += nums[i]
            right_sum = total_sum - left_sum

            # Check if difference is even (same parity)
            if (left_sum - right_sum) % 2 == 0:
                count += 1

        return count

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Dictionary to count occurrences of each number in subarrays
        count = {}

        # Generate all subarrays of size k and count numbers
        for i in range(len(nums) - k + 1):
            subarray = nums[i:i+k]
            # Count unique elements in this subarray
            unique_elements = set(subarray)
            for num in unique_elements:
                count[num] = count.get(num, 0) + 1

        # Find the largest number that appears in exactly one subarray
        result = -1
        for num, freq in count.items():
            if freq == 1:
                result = max(result, num)

        return result

class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        nums.sort()

        # Precompute factorials
        max_n = n + k
        fact = [1] * (max_n + 1)
        for i in range(1, max_n + 1):
            fact[i] = (fact[i-1] * i) % MOD

        def mod_inverse(a, mod):
            return pow(a, mod - 2, mod)

        def comb(n, r):
            if r > n or r < 0:
                return 0
            if r == 0 or r == n:
                return 1
            return (fact[n] * mod_inverse(fact[r], MOD) % MOD) * mod_inverse(fact[n-r], MOD) % MOD

        result = 0

        # For each element in sorted array, calculate its contribution
        for i in range(n):
            # Contribution as minimum element (subsequences where this element is the minimum)
            # Include this element, choose 0 to min(k-1, n-1-i) elements from the right
            right_elements = n - 1 - i
            contribution_min = 0
            for j in range(min(k, right_elements + 1)):
                contribution_min = (contribution_min + comb(right_elements, j)) % MOD

            # Contribution as maximum element (subsequences where this element is the maximum)
            # Include this element, choose 0 to min(k-1, i) elements from the left  
            left_elements = i
            contribution_max = 0
            for j in range(min(k, left_elements + 1)):
                contribution_max = (contribution_max + comb(left_elements, j)) % MOD

            result = (result + (nums[i] * contribution_min) % MOD + (nums[i] * contribution_max) % MOD) % MOD

        return result

class Solution:
    def findValidPair(self, s: str) -> str:
        # Count frequency of each digit
        freq = {}
        for digit in s:
            freq[digit] = freq.get(digit, 0) + 1

        # Check each adjacent pair
        for i in range(len(s) - 1):
            first_digit = s[i]
            second_digit = s[i + 1]

            # Check if digits are different
            if first_digit != second_digit:
                # Check if each digit appears exactly as many times as its value
                if freq[first_digit] == int(first_digit) and freq[second_digit] == int(second_digit):
                    return first_digit + second_digit

        # No valid pair found
        return ""

class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)

        # Calculate gaps between consecutive meetings
        gaps = []

        # Gap from 0 to first meeting
        if startTime[0] > 0:
            gaps.append(startTime[0])

        # Gaps between consecutive meetings
        for i in range(n - 1):
            gap = startTime[i + 1] - endTime[i]
            if gap > 0:
                gaps.append(gap)

        # Gap from last meeting to eventTime
        if eventTime > endTime[-1]:
            gaps.append(eventTime - endTime[-1])

        # Sort gaps in descending order to prioritize larger gaps for rescheduling
        gaps.sort(reverse=True)

        # If we can reschedule k meetings, we can eliminate k gaps (make them 0)
        # The maximum free time would be the maximum among remaining gaps
        if k >= len(gaps):
            return 0

        return gaps[k]

