class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        import heapq

        # Sort each row in descending order
        for i in range(len(grid)):
            grid[i].sort(reverse=True)

        # Create a max heap with the first element of each row
        max_heap = []
        for i in range(len(grid)):
            if len(grid[i]) > 0:
                heapq.heappush(max_heap, (-grid[i][0], i, 0))  # (-value, row, col)

        total_sum = 0
        elements_taken = 0

        # Greedily pick elements
        while max_heap and elements_taken < k:
            neg_val, row, col = heapq.heappop(max_heap)
            val = -neg_val
            total_sum += val
            elements_taken += 1

            # Add next element from the same row if available
            if col + 1 < len(grid[row]):
                heapq.heappush(max_heap, (-grid[row][col + 1], row, col + 1))

        return total_sum

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        def is_non_decreasing(arr):
            for i in range(1, len(arr)):
                if arr[i] < arr[i-1]:
                    return False
            return True

        operations = 0
        current_nums = nums[:]

        while not is_non_decreasing(current_nums):
            # Find minimum adjacent sum pair (leftmost in case of ties)
            min_sum = float('inf')
            min_index = -1

            for i in range(len(current_nums) - 1):
                current_sum = current_nums[i] + current_nums[i+1]
                if current_sum < min_sum:
                    min_sum = current_sum
                    min_index = i

            # Create new array with pair merged at min_index
            new_nums = []
            i = 0
            while i < len(current_nums):
                if i == min_index:
                    # Add the merged element
                    new_nums.append(current_nums[i] + current_nums[i+1])
                    i += 2  # Skip both elements that were merged
                else:
                    new_nums.append(current_nums[i])
                    i += 1

            current_nums = new_nums
            operations += 1

        return operations

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_beautiful(num_str):
            n = len(num_str)
            memo = {}

            def dp(pos, is_limit, product, sum_digits, started):
                # Base case
                if pos == n:
                    # Valid only if we formed a number (started=True) and sum is not zero
                    # and product is divisible by sum
                    if started and sum_digits != 0 and product % sum_digits == 0:
                        return 1
                    return 0

                # Check memo
                if (pos, is_limit, product, sum_digits, started) in memo:
                    return memo[(pos, is_limit, product, sum_digits, started)]

                # Determine the limit for current digit
                limit = int(num_str[pos]) if is_limit else 9
                result = 0

                # Try all possible digits at current position
                for digit in range(0, limit + 1):
                    if not started and digit == 0:
                        # Continue with leading zero
                        result += dp(pos + 1, is_limit and (digit == limit), product, sum_digits, False)
                    else:
                        # We're placing a digit (could be 0 for middle positions)
                        new_product = product * digit if product != 0 else digit
                        new_sum = sum_digits + digit
                        new_started = True
                        result += dp(pos + 1, is_limit and (digit == limit), new_product, new_sum, True)

                memo[(pos, is_limit, product, sum_digits, started)] = result
                return result

            return dp(0, True, 1, 0, False)

        # Handle edge case where l = 1: we want [l, r] inclusive
        # But for digit DP, we count from 1 to r, and 1 to l-1
        return count_beautiful(str(r)) - count_beautiful(str(l - 1))

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Union-Find data structure
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])  # Path compression
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                # Union by rank
                if rank[px] < rank[py]:
                    px, py = py, px
                parent[py] = px
                if rank[px] == rank[py]:
                    rank[px] += 1

        # Calculate intersections and build connections
        for i in range(n):
            set1 = set(properties[i])
            for j in range(i + 1, n):
                set2 = set(properties[j])
                # Calculate intersection size
                intersection_size = len(set1 & set2)
                if intersection_size >= k:
                    union(i, j)

        # Count connected components
        components = set()
        for i in range(n):
            components.add(find(i))

        return len(components)

