def is_colorful_bracket_sequence(s):
    stack = []
    # Map closing brackets to opening brackets
    bracket_map = {
        ')': '(',
        ']': '[',
        '>': '<'
    }

    for char in s:
        if char in '([{<':
            # Opening bracket, push to stack
            stack.append(char)
        elif char in ')]}>':
            # Closing bracket
            if not stack:
                # No opening bracket to match
                return False
            if stack[-1] != bracket_map[char]:
                # Mismatched bracket
                return False
            # Remove the matched opening bracket
            stack.pop()

    # If stack is empty, all brackets were matched
    return len(stack) == 0

