from collections import deque

def is_palindrome(s):
    return s == s[::-1]

def solve():
    N = int(input())
    grid = []
    for _ in range(N):
        grid.append(input().strip())

    # Build adjacency list
    adj = [[] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if grid[i][j] != '-':
                adj[i].append((j, grid[i][j]))

    # Initialize result matrix
    result = [[-1] * N for _ in range(N)]

    # For each start vertex
    for start in range(N):
        # BFS from start vertex
        queue = deque([(start, "", 0)])  # (current_vertex, path_string, path_length)
        visited = {}  # vertex -> set of path_strings seen
        visited[start] = set([""])

        while queue:
            vertex, path_string, length = queue.popleft()

            # If we reached a vertex different from start and the path is palindrome
            if vertex != start and is_palindrome(path_string):
                if result[start][vertex] == -1:
                    result[start][vertex] = length

            # Explore neighbors
            for next_vertex, edge_label in adj[vertex]:
                new_path = path_string + edge_label
                if next_vertex not in visited:
                    visited[next_vertex] = set()
                if new_path not in visited[next_vertex]:
                    visited[next_vertex].add(new_path)
                    queue.append((next_vertex, new_path, length + 1))

    # Handle the case where start == end (path of length 0)
    for i in range(N):
        result[i][i] = 0

    # Output result
    for i in range(N):
        print(" ".join(map(str, result[i])))

