        need_cover = False
        for j in range(L, R + 1):
            if j <= N and not is_one[j]:
                need_cover = True
                break

        # If no positions in [L,R] are 0, we can use operation 0
        if not need_cover:
            result.append(0)
        else:
            # We need to cover some positions. Use operation 1 (cover [L,R])  
            for j in range(L, R + 1):
                if j <= N:
                    is_one[j] = True
            result.append(1)
            total_cost += 1

    # Final check
